struct PanelQuad
{
	char pad[16];
	float mask;
	int mask_enabled;

	void Mask(float value)
	{
		mask = value;
		mask_enabled = 1;
	}
};

#define assert(condition) ((void)0)

struct SurferData
{
	char pad[560];
	int attr_spin;
	int attr_speed;
	int attr_balance;
	int attr_air;
	char tail[76];
};

struct Cheat
{
	int on;

	bool isOn() { return on != 0; }
};

struct Career
{
	int spin;
	int speed;
	int jump;
	int balance;

	int GetSpin() { return spin; }
	int GetSpeed() { return speed; }
	int GetJump() { return jump; }
	int GetBalance() { return balance; }
	int GetSurferIdx();
};

struct FrontEndManager
{
	int tmp_game_mode;
};

enum
{
	CHEAT_UNLOCK_ALL_SKILL_POINTS,
	GAME_MODE_CAREER,
	DISP_HANDICAP = 1
};

extern SurferData SurferDataArray[];
extern Cheat g_session_cheats[];
extern Career *g_career;
extern FrontEndManager frontendmanager;

struct SurferFrontEnd
{
	char pad0[352];
	int disp_state;
	char pad1[192];
	PanelQuad *gauges[4][3];
	PanelQuad *red_gauges[4];
	char pad2[104];
	int hcap;
	char pad3[24];
	int current_surfer_index;

	void MaskWave(int wave);
};

void SurferFrontEnd::MaskWave(int wave)
{
//	int level = SurferDataArray[current_surfer_index].stats[wave];
	int level=0;
	int red_level=0;
	switch(wave)
	{
	case 0:
		level = SurferDataArray[current_surfer_index].attr_spin;
		if (g_session_cheats[CHEAT_UNLOCK_ALL_SKILL_POINTS].isOn())
			red_level = level + 6;
		else
			red_level = g_career->GetSpin();
		break;
	case 1:
		level = SurferDataArray[current_surfer_index].attr_speed;
		if (g_session_cheats[CHEAT_UNLOCK_ALL_SKILL_POINTS].isOn())
			red_level = level + 6;
		else
			red_level = g_career->GetSpeed();
		break;
	case 2:
		level = SurferDataArray[current_surfer_index].attr_air;
		if (g_session_cheats[CHEAT_UNLOCK_ALL_SKILL_POINTS].isOn())
			red_level = level + 6;
		else
			red_level = g_career->GetJump();
		break;
	case 3:
		level = SurferDataArray[current_surfer_index].attr_balance;
		if (g_session_cheats[CHEAT_UNLOCK_ALL_SKILL_POINTS].isOn())
			red_level = level + 6;
		else
			red_level = g_career->GetBalance();
		break;
	default:
		assert(false);
		level = 0;
		red_level = 0;
		break;
	}

	// only show red gauges if same surfer
	if((frontendmanager.tmp_game_mode != GAME_MODE_CAREER || g_career->GetSurferIdx() != current_surfer_index) &&
		!(frontendmanager.tmp_game_mode == GAME_MODE_CAREER && g_session_cheats[CHEAT_UNLOCK_ALL_SKILL_POINTS].isOn()))
		red_level = level;

	// adjust for handicap
	if(disp_state == DISP_HANDICAP)
	{
		if(hcap < 0) level += hcap;
		red_level += hcap;
	}

	static const int MAX_LEVEL = 20;
	float val = ((float) level)/MAX_LEVEL;
	float red_val = ((float) red_level)/MAX_LEVEL;

	if(val > 1) val = 1;
	if(red_val > 1) red_val = 1;

	gauges[wave][1]->Mask(val);
	red_gauges[wave]->Mask(red_val);
}
